/**
 * FICTIONAL demo initiatives. Operational inputs only — all value is computed by the engine.
 */
import type { AgentSpec, InitiativeSpec } from "./generator";

const A = (
  name: string,
  description: string,
  model: AgentSpec["model"],
  share: number,
  automation: number,
  hitl: AgentSpec["hitl"],
  automated: string[],
  augmented: string[] = [],
  tokens?: { in?: number; out?: number; calls?: number },
): AgentSpec => ({ name, description, model, share, automation, hitl, automated, augmented, tokensIn: tokens?.in, tokensOut: tokens?.out, calls: tokens?.calls });

const D = (cashable: number, costAvoidance: number, redeployed: number, revenueProducing: number, rationale: string) => ({
  cashable,
  costAvoidance,
  redeployed,
  revenueProducing,
  unallocated: Math.max(0, Math.round((1 - cashable - costAvoidance - redeployed - revenueProducing) * 1000) / 1000),
  rationale,
});

